#include "mux.h"
#include <string.h>
static const unsigned char pat[]={0x00,0xb0,0x0d,0x00,0x00,0xc1,0x00,0x00,0x00,0x01,0xe0,0x10,0x2d,0x50,0x98,0x1b};
static const unsigned char pmt[]={0x02,0xb0,0x21,0x00,0x01,0xc1,0x00,0x00,0xf0,0x00,0xf0,0x00,0x1b,0xe0,0x11,0xf0,0x0f,0x2a,0x07,0x7f,0xff,0x00,0x00,0x05,0xdd,0xdf,0x28,0x04,0x42,0x80,0x32,0x3f,0xfe,0xe6,0x1f,0x98};
static int fail(struct live_mux *m){if(m)m->failed=1;return -1;}
static int time_at(struct live_mux *m,uint64_t ms){if(!m||m->failed||!m->write)return fail(m);if(m->timed&&ms<m->last_ms)return fail(m);m->timed=1;m->last_ms=ms;return 0;}
static int emit(struct live_mux *m,const unsigned char p[188]){return m->write(m->opaque,p,188)==188?0:fail(m);}
static int payload(struct live_mux *m,unsigned pid,unsigned idx,const unsigned char *data,size_t n,int start){unsigned char p[188];size_t spare=184-n,off=4;if(!n||n>184)return fail(m);memset(p,0xff,sizeof(p));p[0]=0x47;p[1]=(pid>>8)|(start?0x40:0);p[2]=pid;p[3]=(spare?0x30:0x10)|(m->cc[idx]&15);m->cc[idx]=(m->cc[idx]+1)&15;if(spare){p[off++]=spare-1;if(spare>1)p[off]=0;off=4+spare;}memcpy(p+off,data,n);return emit(m,p);}
static void stamp(unsigned char *p,uint64_t value,unsigned prefix){value&=0x1ffffffffULL;p[0]=prefix|((value>>29)&14)|1;p[1]=value>>22;p[2]=((value>>14)&254)|1;p[3]=value>>7;p[4]=((value<<1)&254)|1;}
static unsigned prefix(const unsigned char *p,size_t n){if(n>=4&&!p[0]&&!p[1]&&!p[2]&&p[3]==1)return 4;if(n>=3&&!p[0]&&!p[1]&&p[2]==1)return 3;return 0;}
static unsigned scan(const unsigned char *p,size_t n){size_t i=0;unsigned f=0,k,t;if(!p||!n||!prefix(p,n))return 32;while(i<n){k=prefix(p+i,n-i);if(!k){i++;continue;}i+=k;if(i==n||p[i]&128)return 32;t=p[i++]&31;if(!t||t>=24)return 32;if(t==5)f|=LIVE_IDR|LIVE_SLICE;if(t==1)f|=LIVE_SLICE;if(t==7)f|=LIVE_SPS;if(t==8)f|=LIVE_PPS;}return f;}
void live_mux_init(struct live_mux *m,ssize_t (*write)(void *,const void *,size_t),void *opaque){memset(m,0,sizeof(*m));m->write=write;m->opaque=opaque;}
int live_mux_tick(struct live_mux *m,uint64_t ms){unsigned char p[188],s[37];uint32_t base;if(time_at(m,ms))return -1;if(!m->psi||ms-m->psi_ms>=332){s[0]=0;memcpy(s+1,pat,sizeof(pat));if(payload(m,0,0,s,sizeof(pat)+1,1))return -1;memcpy(s+1,pmt,sizeof(pmt));if(payload(m,16,1,s,sizeof(pmt)+1,1))return -1;m->psi=1;m->psi_ms=ms;}if(!m->pcr||ms-m->pcr_ms>=32){base=(uint32_t)(90*ms);memset(p,0xff,sizeof(p));p[0]=0x47;p[1]=0x10;p[2]=0;p[3]=0x20;p[4]=183;p[5]=0x10;p[6]=base>>25;p[7]=base>>17;p[8]=base>>9;p[9]=base>>1;p[10]=((base&1)<<7)|0x7e;p[11]=0;if(emit(m,p))return -1;m->pcr=1;m->pcr_ms=ms;}return 0;}
int live_mux_push(struct live_mux *m,const void *data,size_t n,uint32_t flags,uint64_t ms){const unsigned char *au=data;unsigned actual;unsigned char pes[19],part[184];size_t total,at=0;if(time_at(m,ms))return -1;if(!n||n>LIVE_AU_LIMIT||flags>31)return fail(m);actual=scan(au,n);if(actual==32||!(actual&LIVE_SLICE)||actual!=(flags&15))return fail(m);if((!m->started||(flags&LIVE_RESYNC))&&(actual&7)!=7)return 0;m->started=1;if(live_mux_tick(m,ms))return -1;memset(pes,0,sizeof(pes));pes[2]=1;pes[3]=0xe0;total=n+13;if(total<=65535){pes[4]=total>>8;pes[5]=total;}pes[6]=0x80;pes[7]=0xc0;pes[8]=10;stamp(pes+9,(uint32_t)(90*ms)+1ULL,0x30);stamp(pes+14,(uint32_t)(90*ms),0x10);total=n+sizeof(pes);while(at<total){size_t count=total-at,done=0,head;if(count>184)count=184;if(at<sizeof(pes)){head=sizeof(pes)-at;if(head>count)head=count;memcpy(part,pes+at,head);done=head;}if(done<count)memcpy(part+done,au+at+done-sizeof(pes),count-done);if(payload(m,17,2,part,count,at==0))return -1;at+=count;}return 1;}
